452: function updateTennis() {
453:   // Update ball position
454:   const ball = gameState.tennis.ball;
455:   ball.x += ball.vx;
456:   ball.y += ball.vy;
457:   
458:   // Apply gravity/friction
459:   ball.vy += 0.5;
460:   ball.vx *= 0.99;
