578: function updateGolf() {
579:   const g = gameState.golf;
580:   if (g.power > 0) {
581:     g.ball.vx = Math.cos(g.aimAngle) * g.power * 0.1;
582:     g.ball.vy = Math.sin(g.aimAngle) * g.power * 0.1;
583:     g.power *= 0.99; // Decay power
584:     
585:     // Apply wind
586:     g.ball.vx += g.wind * 0.5;
587:   }
588:   
589:   g.ball.x += g.ball.vx;
590:   g.ball.y += g.ball.vy;
591:   
592:   // Simple friction
593:   g.ball.vx *= 0.999;
594:   g.ball.vy *= 0.999;
595:   
596:   // Update DOM
597:   const ballEl = document.getElementById('golf-ball');
598:   ballEl.style.left = `${g.ball.x}px`;
599:   ballEl.style.top = `${g.ball.y}px`;
600:   
601:   // Check if in hole
602:   const dx = g.ball.x - g.holePosition.x;
603:   const dy = g.ball.y - g.holePosition.y;
604:   const distance = Math.sqrt(dx * dx + dy * dy);
605:   if (distance < 30) {
606:     // Hole in one!
607:     console.log('Hole in one!');
608:   }
609: }
