351: .tennis-btn {
352:   background: var(--wii-green);
353:   color: white;
354:   border-color: var(--wii-green);
355: }
356: 
357: .tennis-btn:hover {
358:   background: #54c466;
359:   box-shadow: 0 4px 12px rgba(115, 173, 33, 0.4);
360: }
361: 
362: /* Baseball HUD */
363: .baseball-btn {
364:   background: var(--wii-red);
365:   color: white;
366:   border-color: var(--wii-red);
367: }
368: 
369: .baseball-btn:hover {
370:   background: #e84118;
371:   box-shadow: 0 4px 12px rgba(228, 26, 28, 0.4);
372: }
373: 
374: /* Golf HUD */
375: .golf-btn {
376:   background: var(--wii-orange);
377:   color: white;
378:   border-color: var(--wii-orange);
379: }
380: 
381: .golf-btn:hover {
382:   background: #ff7c40;
383:   box-shadow: 0 4px 12px rgba(255, 107, 53, 0.4);
384: }
385: 
386: /* Bowling HUD */
387: .bowling-btn {
388:   background: var(--wii-blue);
389:   color: white;
390:   border-color: var(--wii-blue);
391: }
392: 
393: .bowling-btn:hover {
394:   background: #5a9fd8;
395:   box-shadow: 0 4px 12px rgba(58, 151, 217, 0.4);
396: }
397: 
398: /* Boxing HUD */
399: .box-btn {
400:   background: var(--wii-red);
401:   color: white;
402:   border-color: var(--wii-red);
403: }
404: 
405: .box-btn:hover {
406:   background: #e84118;
407:   box-shadow: 0 4px 12px rgba(228, 26, 28, 0.4);
408: }

