mkdir -p screenshots && node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 850 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') errors.push(message.text()); });
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.locator('#start-button').click();
  const sports = ['tennis', 'baseball', 'golf', 'boxing', 'bowling'];
  for (const sport of sports) {
    await page.locator(`[data-sport="${sport}"]`).click();
    await page.locator('#game-canvas').evaluate(canvas => canvas.dispatchEvent(new KeyboardEvent('keydown', { key: ' ' })));
    await page.keyboard.press('Space');
    const title = await page.locator('#game-name').textContent();
    if (!title.toLowerCase().includes(sport)) throw new Error(`Wrong sport loaded: ${sport} -> ${title}`);
    await page.locator('[data-back]').first().click();
  }
  await page.locator('#creator-button').click();
  await page.locator('[data-feature="hair"]').click();
  await page.locator('[data-feature="glasses"]').click();
  await page.locator('#player-name').fill('Island Ace');
  const profile = await page.locator('#profile-name').textContent();
  if (!profile.includes('ISLAND ACE')) throw new Error(`Creator name not reflected: ${profile}`);
  await page.locator('[data-back]').first().click();
  await page.locator('#online-button').click();
  await page.waitForTimeout(11200);
  const matchmakingResult = await page.locator('#game-screen').evaluate(element => element.classList.contains('active'));
  if (!matchmakingResult) throw new Error('Matchmaking did not enter a game after 10 seconds');
  await page.locator('#game-canvas').screenshot({ path: 'screenshots/island-club.jpg', type: 'jpeg', quality: 58 });
  const result = {
    titleScreenStarted: true,
    sportsTested: sports,
    creatorProfile: profile,
    matchmakingEnteredGame: matchmakingResult,
    screenshot: 'screenshots/island-club.jpg',
    browserErrors: errors
  };
  console.log(JSON.stringify(result, null, 2));
  await browser.close();
  if (errors.length) process.exitCode = 1;
})().catch(error => { console.error(error); process.exitCode = 1; });
NODE

