const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});
 const bad=[];
 page.on('requestfailed',r=>bad.push({kind:'failed request',url:r.url(),error:r.failure()?.errorText}));
 page.on('response',r=>{if(r.status()>=400)bad.push({kind:'http',status:r.status(),url:r.url()})});
 page.on('console',m=>{if(m.type()==='error')bad.push({kind:'console',text:m.text(),location:m.location()})});
 page.on('pageerror',e=>bad.push({kind:'pageerror',text:e.message}));
 await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
 await page.locator('#start-button').click();
 await page.waitForTimeout(500);
 await page.screenshot({path:'screenshots/island-club.jpg',type:'jpeg',quality:68,fullPage:true});
 const details=await page.evaluate(()=>({viewport:[innerWidth,innerHeight],document:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],active:document.querySelector('.screen.active')?.id}));
 console.log(JSON.stringify({details,bad},null,2));
 await browser.close();
})();
