const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});
 const errors=[];
 page.on('requestfailed',r=>errors.push(`request ${r.url()}: ${r.failure()?.errorText}`));
 page.on('response',r=>{if(r.status()>=400)errors.push(`HTTP ${r.status()} ${r.url()}`)});
 page.on('console',m=>{if(m.type()==='error')errors.push(`${m.text()} (${m.location().url})`)});
 page.on('pageerror',e=>errors.push(`page error: ${e.message}`));
 await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
 await page.locator('#start-button').click();
 const sports=['tennis','baseball','golf','boxing','bowling'];
 for(const sport of sports){
  await page.locator(`[data-sport="${sport}"]`).click();
  const title=await page.locator('#game-name').textContent();
  if(!title.toLowerCase().includes(sport))throw new Error(`${sport} opened as ${title}`);
  await page.keyboard.press('Space');
  await page.waitForTimeout(300);
  const msg=await page.locator('#game-message').textContent();
  if(msg==='Ready when you are.')throw new Error(`${sport} action did not fire`);
  await page.locator('#game-screen [data-back]').click();
 }
 await page.locator('#creator-button').click();
 await page.locator('[data-feature="hair"]').click();
 await page.locator('[data-feature="glasses"]').click();
 await page.locator('#player-name').fill('Island Ace');
 const profile=await page.locator('#profile-name').textContent();
 if(profile!=='ISLAND ACE')throw new Error(`Unexpected profile name: ${profile}`);
 await page.locator('#creator-screen [data-back]').first().click();
 await page.locator('#online-button').click();
 await page.waitForTimeout(11200);
 const matchmaking=await page.locator('#game-screen').evaluate(el=>el.classList.contains('active'));
 if(!matchmaking)throw new Error('Matchmaking did not start a match');
 await page.locator('#game-screen [data-back]').click();
 await page.locator('#lobby-screen').waitFor({state:'visible'});
 await page.screenshot({path:'screenshots/island-club.jpg',type:'jpeg',quality:68,fullPage:true});
 const screenshot=await page.evaluate(()=>({width:document.documentElement.scrollWidth,height:document.documentElement.scrollHeight,active:document.querySelector('.screen.active')?.id}));
 console.log(JSON.stringify({sportsTested:sports,creatorProfile:profile,matchmakingEnteredGame:matchmaking,screenshot:`screenshots/island-club.jpg (${screenshot.width}×${screenshot.height}, ${screenshot.active})`,browserErrors:errors},null,2));
 await browser.close();
 if(errors.length)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1});
